// Kilat for Cairn. Runs ```kilat code blocks in your notes and shows the result under the code.
//
// Install: in Cairn open Plugins, choose "Install from GitHub or a link" and type juw12/kilat.
//
// This file is generated by build.py from cairn/main.template.js, docs/kilat.js and
// docs/kilat.wasm. Change those and run `python build.py web`; do not edit this file by hand.
// The program in a block runs inside a WebAssembly sandbox: it has no access to files, the
// network or the note, and it is stopped when it runs too long or uses too much memory.

export const manifest = {
  id: "kilat",
  name: "Kilat",
  version: "KILAT_VERSION",
  author: "Juwen Lie",
  description: "Runs kilat code blocks in your notes: calculations with units, checked before they run.",
  minApi: 1,
};

const LIMITS = { fuel: 20_000_000, memoryMb: 64, printLast: true };
const REMEMBERED_RESULTS = 60;

const EXAMPLE = [
  "```kilat",
  "let force = 250 N",
  "let area = 12 mm^2",
  'print("stress = {force / area:MPa.1}")',
  "```",
  "",
].join("\n");

const TIME_LIMIT_MS = 10_000;
const TIME_LIMIT_NOTE = "Stopped after 10 seconds. The program was still working.";

const STYLE = `
.kilat-block { margin: 0.8em 0; border: 1px solid var(--line, #d6d3cd); border-radius: 6px; overflow: hidden; }
.kilat-block pre { margin: 0; padding: 0.7em 0.9em; border: 0; border-radius: 0; background: none; white-space: pre-wrap; overflow-wrap: anywhere; }
.kilat-block .kilat-result { border-top: 1px solid var(--line, #d6d3cd); border-left: 3px solid var(--accent, #b45309); color: var(--ink, inherit); }
.kilat-block .kilat-error { color: #d4442e; }
.kilat-block .kilat-note { opacity: 0.65; }
`;

/*KILAT_GLUE*/

const PACKED_WASM = "KILAT_WASM";

// The WebAssembly module travels inside this file, zlib-compressed and base64-encoded,
// because Cairn installs a plugin as one file of at most 400,000 characters.
async function unpack(text) {
  const packed = Uint8Array.from(atob(text), (letter) => letter.charCodeAt(0));
  const stream = new Blob([packed]).stream().pipeThrough(new DecompressionStream("deflate"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

let starting = null;

function engine() {
  if (!starting) {
    starting = unpack(PACKED_WASM).then(loadKilat);
    starting.catch(() => {
      starting = null;
    });
  }
  return starting;
}

// A note has no stop button, so the clock stops a program that works for too long.
function timedRun(kilat, source) {
  const stop = new AbortController();
  const timer = setTimeout(() => stop.abort(), TIME_LIMIT_MS);
  return kilat.run(source, { ...LIMITS, signal: stop.signal }).then((outcome) => {
    clearTimeout(timer);
    return outcome.kind === "stopped" ? { ...outcome, error: TIME_LIMIT_NOTE } : outcome;
  });
}

// Cairn draws a note again whenever it changes, so results are remembered by program text.
const remembered = new Map();

function resultOf(source) {
  let pending = remembered.get(source);
  if (!pending) {
    pending = engine()
      .then((kilat) => timedRun(kilat, source))
      .catch((problem) => ({
        ok: false,
        output: "",
        error: `Kilat could not start: ${problem?.message ?? problem}`,
        kind: "crash",
      }));
    remembered.set(source, pending);
    if (remembered.size > REMEMBERED_RESULTS) remembered.delete(remembered.keys().next().value);
  }
  return pending;
}

function element(tag, className, text) {
  const node = document.createElement(tag);
  node.className = className;
  node.textContent = text;
  return node;
}

function show(box, outcome) {
  box.replaceChildren();
  if (outcome.output) box.append(element("span", "kilat-output", outcome.output));
  if (!outcome.ok) box.append(element("span", "kilat-error", outcome.error));
  if (outcome.ok && !outcome.output) box.append(element("span", "kilat-note", "(no output)"));
  box.dataset.kilat = outcome.ok ? "ok" : outcome.kind || "error";
}

// Cairn replaces the code block with `out`, so the program text is shown again above its result.
function draw(source, out) {
  out.classList.add("kilat-block");
  out.replaceChildren();
  const result = element("pre", "kilat-result", "running\u2026");
  result.dataset.kilat = "running";
  out.append(element("pre", "kilat-source", source.replace(/\n$/, "")), result);
  resultOf(source).then((outcome) => show(result, outcome));
}

export default function activate(cairn) {
  cairn.addStyle(STYLE);
  cairn.registerCodeBlock("kilat", draw);
  cairn.addCommand({
    id: "insert-example",
    name: "Kilat: insert an example block",
    run: () => cairn.insertIntoActiveNote(EXAMPLE),
  });
  cairn.addCommand({
    id: "run-again",
    name: "Kilat: run the blocks again",
    run: () => {
      remembered.clear();
      cairn.rerender?.();
    },
  });
  return () => remembered.clear();
}
